/**
 * The agent's optional `slack-manifest.json`: the exact bot scopes its
 * Slack app requests in place of the defaults. `slack create` reads it
 * here. The control plane decides which lists are allowed.
 */
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { describeError, describeErrorCode } from "./describe-error.js";
import { CHAT_WRITE_CUSTOMIZE_SCOPE } from "./slack-bot-scopes.js";
export const SLACK_MANIFEST_OPT_IN_FILE = "slack-manifest.json";
/**
 * Reads the file, if any. With a `botScopes` list, `chatWriteCustomize`
 * folds into it. Returns an exit code, error already rendered, when the file
 * is unreadable or malformed.
 */
export async function readSlackManifestOptIn(dir, err) {
    let text;
    try {
        text = await readFile(join(dir, SLACK_MANIFEST_OPT_IN_FILE), "utf8");
    }
    catch (error) {
        if (describeErrorCode(error) === "ENOENT") {
            return {};
        }
        err(`Could not read ${SLACK_MANIFEST_OPT_IN_FILE}: ${describeError(error)}\n`);
        return 1;
    }
    let parsed;
    try {
        parsed = JSON.parse(text);
    }
    catch {
        err(`${SLACK_MANIFEST_OPT_IN_FILE} is not valid JSON.\n`);
        return 1;
    }
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
        err(`${SLACK_MANIFEST_OPT_IN_FILE} must be a JSON object.\n`);
        return 1;
    }
    const { chatWriteCustomize, botScopes } = parsed;
    if (chatWriteCustomize !== undefined && typeof chatWriteCustomize !== "boolean") {
        err(`${SLACK_MANIFEST_OPT_IN_FILE} chatWriteCustomize must be true or false.\n`);
        return 1;
    }
    if (botScopes === undefined) {
        return chatWriteCustomize === undefined ? {} : { chatWriteCustomize };
    }
    if (!(Array.isArray(botScopes) &&
        botScopes.every((scope) => typeof scope === "string"))) {
        err(`${SLACK_MANIFEST_OPT_IN_FILE} botScopes must be an array of Slack bot scope strings, for example ["chat:write", "pins:read"].\n`);
        return 1;
    }
    const scopes = botScopes.filter((scope) => scope !== CHAT_WRITE_CUSTOMIZE_SCOPE);
    if (!(chatWriteCustomize ?? botScopes.includes(CHAT_WRITE_CUSTOMIZE_SCOPE))) {
        return { botScopes: scopes };
    }
    const at = scopes.indexOf("chat:write");
    return {
        botScopes: at === -1
            ? [...scopes, CHAT_WRITE_CUSTOMIZE_SCOPE]
            : [...scopes.slice(0, at + 1), CHAT_WRITE_CUSTOMIZE_SCOPE, ...scopes.slice(at + 1)],
    };
}
